    }
}

impl Deref for AgentReplayHistory {
    type Target = VecDeque<AgentEventEnvelope>;

    fn deref(&self) -> &Self::Target {
        &self.envelopes
    }
}

impl AgentEventBus {
    #[cfg_attr(not(test), allow(dead_code))]
