impl PlannerStreamLifecycle {
    fn transition(&mut self, kind: PlannerStreamKind, state: EventSourceState) {
        match kind {
            PlannerStreamKind::Agent => self.agent = state,
            PlannerStreamKind::Permission => self.permission = state,
        }
    }

