    }
}

#[derive(Default)]
struct PlannerStreamSources {
    session_id: String,
    generation: u64,
    agent: Option<EventSource>,
    permission: Option<EventSource>,
    projection: Option<EventSource>,
    canvas: Option<EventSource>,
    lifecycle: PlannerStreamLifecycle,
}

impl PlannerStreamSources {
    fn reset(&mut self, session_id: String, generation: u64) {
        // Dropping gloo-net EventSource calls close(), so take every transport
        // before installing the next generation. One owner prevents idle stale
        // streams from surviving a focus change and consuming browser sockets.
        self.agent.take();
        self.permission.take();
        self.projection.take();
        self.canvas.take();
        *self = Self {
            session_id,
            generation,
            ..Self::default()
        };
    }
}

