    let last_turn_finished = decode_state(&projection.state.last_turn_finished, |event| {
        matches!(event, AgentEvent::TurnFinished { .. })
    })?;
    let model_rerouted = decode_state(&projection.state.model_rerouted, |event| {
        matches!(event, AgentEvent::ModelRerouted { .. })
    })?;
    let permissions = projection
        .state
        .pending_permissions
        .iter()
        .map(|value| {
            permission_from_projection(value, &detail.id).ok_or(ProjectionPreparation::Invalid)
        })
        .collect::<Result<Vec<_>, _>>()?;

    Ok(PreparedProjection {
        active_turn,
        last_turn_finished,
        model_rerouted,
        browser_active: projection.state.browser_active,
        detail,
        turns,
        pinned,
        cursor: projection.cursor,
        lease_id: projection.lease_id,
        permissions,
    })
}

